-- Equipment reference import from Good Cents R&M Equipment Reference PDF.
-- Source PDF metadata: created 2026-06-01; imported for FarmingdaleIQ maintenance on 2026-08-05.

create table public.equipment_support_contacts (
  id uuid primary key default gen_random_uuid(),
  equipment_id uuid not null references public.equipment(id) on delete cascade,
  label text not null,
  value text not null,
  href text,
  sort_order int not null default 0
);

create table public.equipment_parts (
  id uuid primary key default gen_random_uuid(),
  equipment_id uuid not null references public.equipment(id) on delete cascade,
  name text not null,
  part_number text,
  order_url text not null,
  url_type text not null default 'part_buy' check (url_type in ('part_buy', 'parts_search')),
  source_page int,
  sort_order int not null default 0,
  notes text
);

create table public.equipment_pm_tasks (
  id uuid primary key default gen_random_uuid(),
  equipment_id uuid not null references public.equipment(id) on delete cascade,
  title text not null,
  details text,
  sort_order int not null default 0
);

create table public.equipment_reference_sections (
  id uuid primary key default gen_random_uuid(),
  equipment_id uuid not null references public.equipment(id) on delete cascade,
  section_type text not null check (section_type in ('reference', 'troubleshooting')),
  title text not null,
  body text not null,
  source_page int,
  sort_order int not null default 0
);

alter table public.equipment_files
  add column sort_order int not null default 0;

create index equipment_support_contacts_equipment_id_idx on public.equipment_support_contacts(equipment_id, sort_order);
create index equipment_files_equipment_id_sort_idx on public.equipment_files(equipment_id, sort_order);
create index equipment_parts_equipment_id_idx on public.equipment_parts(equipment_id, sort_order);
create index equipment_pm_tasks_equipment_id_idx on public.equipment_pm_tasks(equipment_id, sort_order);
create index equipment_reference_sections_equipment_id_idx on public.equipment_reference_sections(equipment_id, sort_order);

alter table public.equipment_support_contacts enable row level security;
create policy default_deny on public.equipment_support_contacts for all using (false) with check (false);
create policy equipment_support_contacts_select_authenticated on public.equipment_support_contacts
  for select
  using (auth.uid() is not null);
create policy equipment_support_contacts_write_manager on public.equipment_support_contacts
  for all
  using (public.has_permission('maintenance.manage'))
  with check (public.has_permission('maintenance.manage'));

alter table public.equipment_parts enable row level security;
create policy default_deny on public.equipment_parts for all using (false) with check (false);
create policy equipment_parts_select_authenticated on public.equipment_parts
  for select
  using (auth.uid() is not null);
create policy equipment_parts_write_manager on public.equipment_parts
  for all
  using (public.has_permission('maintenance.manage'))
  with check (public.has_permission('maintenance.manage'));

alter table public.equipment_pm_tasks enable row level security;
create policy default_deny on public.equipment_pm_tasks for all using (false) with check (false);
create policy equipment_pm_tasks_select_authenticated on public.equipment_pm_tasks
  for select
  using (auth.uid() is not null);
create policy equipment_pm_tasks_write_manager on public.equipment_pm_tasks
  for all
  using (public.has_permission('maintenance.manage'))
  with check (public.has_permission('maintenance.manage'));

alter table public.equipment_reference_sections enable row level security;
create policy default_deny on public.equipment_reference_sections for all using (false) with check (false);
create policy equipment_reference_sections_select_authenticated on public.equipment_reference_sections
  for select
  using (auth.uid() is not null);
create policy equipment_reference_sections_write_manager on public.equipment_reference_sections
  for all
  using (public.has_permission('maintenance.manage'))
  with check (public.has_permission('maintenance.manage'));

