  select distinct on (lower(name)) lower(name) as name_key, id
  from public.equipment
  order by lower(name), id
), matched as (
  select seed_rows.id, equipment_match.id as equipment_id, seed_rows.label, seed_rows.value, seed_rows.href, seed_rows.sort_order
  from seed_rows
  join equipment_match on equipment_match.name_key = lower(seed_rows.equipment_name)
)
insert into public.equipment_support_contacts (id, equipment_id, label, value, href, sort_order)
select id, equipment_id, label, value, href, sort_order from matched
where not exists (
  select 1 from public.equipment_support_contacts existing where existing.id = matched.id
);

