), equipment_match as (
  select distinct on (lower(name)) lower(name) as name_key, id
  from public.equipment
  order by lower(name), id
), matched as (
  select seed_rows.id, equipment_match.id as equipment_id, seed_rows.label, seed_rows.file_url, seed_rows.sort_order
  from seed_rows
  join equipment_match on equipment_match.name_key = lower(seed_rows.equipment_name)
)
insert into public.equipment_files (id, equipment_id, label, file_url, sort_order)
select id, equipment_id, label, file_url, sort_order from matched
on conflict (id) do update set
  equipment_id = excluded.equipment_id,
  label = excluded.label,
  file_url = excluded.file_url,
  sort_order = excluded.sort_order;

