), equipment_match as (
  select distinct on (lower(name)) lower(name) as name_key, id
  from public.equipment
  order by lower(name), id
), matched as (
  select seed_rows.id, equipment_match.id as equipment_id, seed_rows.name, seed_rows.part_number, seed_rows.order_url, seed_rows.url_type, seed_rows.source_page, seed_rows.sort_order
  from seed_rows
  join equipment_match on equipment_match.name_key = lower(seed_rows.equipment_name)
)
insert into public.equipment_parts (id, equipment_id, name, part_number, order_url, url_type, source_page, sort_order)
select id, equipment_id, name, part_number, order_url, url_type, source_page, sort_order from matched
where not exists (
  select 1 from public.equipment_parts existing where existing.id = matched.id
);

