    ('5981948a-8e74-5d59-a2dc-4dfef3988c96'::uuid, 'BKI Fry Warmer', 'INSPECT UNIT TO MAKE SURE HEATER IS WORKING PROPERLY', 'With unit on, place your hand near the top of the carton holding area, being sure not to touch the top. You should be able to feel significant heat coming from the heating elements.', 1),
    ('7a89c1d9-3eff-513a-a974-7e0aa90fac81'::uuid, 'BKI Fry Warmer', 'INSPECT BLOWER TO MAKE SURE ITS OPERATIONAL', 'With unit on, place your hand near the holes in the warming well. You should be able to feel significant heat coming from the blower elements.', 2),
    ('fd1ca7fd-0b92-55f5-9216-8b17ce39ce95'::uuid, 'BKI Fry Warmer', 'CLEAN BUILD-UP/DUST OFF UNIT', 'With the machine off, separate the base from the perforated warming well by tilting back the base. Wipe down the front of the base where the two meet. Clean out the air intake screen using a mild soap water solution. Dry off the unit and reinstall', 3),
    ('58a2da64-1da4-5661-aa08-d5b784104100'::uuid, 'BKI Fry Warmer', 'INSPECT UNIT FOR WEAR/MISSING PARTS', null, 4),
