    ('ac3dd186-4597-5cfa-9494-f250cb5be75d'::uuid, 'BKI Pass Thru Chute', 'TIGHTEN FACE PLATE/SLAT HOLDER', null, 5),
    ('34d66d4e-7418-54ad-9b0a-ddd77d22f231'::uuid, 'Garland Grill', 'INSPECT/REPLACE GRILL ROLLER', 'Look for any tears or rips in the roller. If these rollers have damage they can leave fragments on the food and become a possible food safety risk.', 1),
    ('3934330d-0062-57f2-ae98-c55978e9c935'::uuid, 'Garland Grill', 'INSPECT/REPLACE GRILL BRUSH HEAD', 'A properly cleaned grill grate is important to properly cooked chicken. Making sure the grill brush is in good shape will help the team properly clean the grill during daily use.', 2),
    ('fef38dd7-e9f6-5187-b03b-14ca4a99b585'::uuid, 'Garland Grill', 'DEEP CLEAN OF UNIT', 'Take the time to clean all of the exposed areas. If you have neglected this job in the past it may take a while to get it back to a base level clean. Just try to get it a little better every month and before long it will be looking like new.', 3),
    ('23f7decc-1608-5ea4-8f28-d1e42bc88a8a'::uuid, 'Garland Grill', 'INSPECT UNIT FOR WEAR/MISSING PARTS', 'Look for anything that seems broken or worn. It is best to replace parts when they still have a little life left in them.', 4),
    ('19da483d-89d4-595b-98b0-d173511eabbd'::uuid, 'Garland Grill', 'INSPECT SLOPE OF CASTERS', 'The back of the machine must be 1/2" higher than the the front to promote forward grease flow. Adjust the casters so the back is at 34" high and the front is at 33.5" high. Be sure to measure from floor to lower grill cook surface. Adjust the unit by turning the casters clockwise to raise the unit and counterclockwise to lower the unit. Caster Slope (Photo by Garland)', 5),
    ('73210ca1-f499-5e58-970e-d31aa22cd2c4'::uuid, 'Garland Grill', 'INSPECT GRATES FOR WARPING/CRACKING', 'After cleaning the grate really well, inspect for cracking or other visible damage. Damage to the grate will effect the overall quality of the product being made on the grill. If cracking or damage are observed contact a tech right away to remedy the issue.', 6),
    ('2249906b-5fc2-511f-81dc-cd613b0cbec5'::uuid, 'Garland Grill', 'REPLACE SHAFT SEAL/RESET TIMER FOR SHAFT SEAL', 'We recommend that this maintenance be done by a Certified Garland Tech. It cost money to get the work done but it is extremely important to the life of the machine. It needs to be done once a year to insure oil does not leak into the actuator and eventually onto your boards costing thousands of dollars in repairs.', 7),
    ('18183875-7b5f-57bc-90f9-99cc0e993abb'::uuid, 'Henny Penny CFE 410 / 420', 'INSPECT UNIT FOR WORN/MISSING PARTS', 'Look for anything that seems broken or worn. It is best to replace parts when they still have a little life left in them.', 1),
    ('bf394d8a-8a94-5317-85da-d9a84bc0edd0'::uuid, 'Henny Penny CFE 410 / 420', 'INSPECT PUMP ASSEMBLY PARTS FOR WEAR/BUILD-UP', 'There are two ways to inspect the pump assembly parts. The first is to remove the pump from the machine, disassemble the components and visually inspect the parts (CLICK HERE FOR VIDEO EXPLAINING THIS PROCESS). The second way is much easier but will not tell you as much. With the oil in the filter pan, disconnect the filter from the pick up tube and put your thumb on the pick up tube. Turn the switch to pump. If you have a weak or no suction then its a possibility you have a bad pump parts and we recommend a visual inspection of the pump.', 2),
    ('511db436-0e79-527d-8c27-4675142c6477'::uuid, 'Henny Penny CFE 410 / 420', 'INSPECT PUMP SEAL FOR LEAKAGE', 'If there is oil leaking between the pump and the motor you will need to replace the pump seal.', 3),
    ('6c9e76b1-997e-5f99-8a60-4cfaefe6aae9'::uuid, 'Henny Penny CFE 410 / 420', 'CLEAN UNDERSIDE OF HENNYS (ONE HENNY A MONTH)', 'By doing this often you will insure that the machine is clean and well cared for.', 4),
    ('53734bdb-945a-5340-8472-77b22a7b6fc2'::uuid, 'Henny Penny CFE 410 / 420', 'INSPECT FILTER PAN O-RINGS', null, 5),
    ('eacee38d-4147-59de-8e3b-1139849a44b9'::uuid, 'Henny Penny CFE 410 / 420', 'INSPECT OIL RESERVOIR O-RING', null, 6),
