    ('810dda66-d6ce-52ee-88a2-6aff7544ab58'::uuid, 'Henny Penny CFE 415', 'CLEAN UNDERSIDE OF HENNYS (ONE HENNY A MONTH)', 'By doing this often you will insure that the machine is clean and well cared for.', 4),
