    ('d712e454-d4ea-5b90-870a-129d279ae032'::uuid, 'Henny Penny PFE 500', 'INSPECT LOCKING COLLAR PIN FOR BREAKAGE OR RESEAT PIN', 'Henny Penny has recently updated the pin used in the spindle assembly. They no longer sell individual parts to this assembly and the whole arm must be replaced. View the "Issue with the Lid?" section on the machines home page. (CLICK HERE TO VIEW)', 9),
    ('88a1c957-0e6d-58a2-a042-a04a3a17b5c7'::uuid, 'Henny Penny PFE 500', 'REVERSE LID GASKET (REPLACE IF NEEDED)', 'VIDEO MEMBERS CLICK HERE FOR ADDITIONAL VIDEO', 10),
    ('b032d760-7135-568f-b69d-090bfaec37fb'::uuid, 'Henny Penny PFE 500', 'INSPECT AND PERFORM LIMIT STOP ADJUSTMENTS', null, 11),
