    ('b5821bd7-0303-574b-a89e-f6c5e78c4ca1'::uuid, 'KanPak Milkshake Base Dispenser', 'DEEP CLEAN', 'Deep clean the inside, drip tray, gaskets and valves mentioned above.', 2),
    ('0509ba9c-afb5-585f-9249-6ec002198708'::uuid, 'KanPak Milkshake Base Dispenser', 'INSPECT FOR WORN OR BROKEN PARTS', 'Inspect the gasket, hinges, latch and valves to ensure they are in proper working order.', 3),
    ('58543c21-5944-596d-96e2-e685f2399bfd'::uuid, 'KanPak Milkshake Base Dispenser', 'CLEAN THE CONDENSER', 'Every 6 months, remove the back panel of the dispenser and inspect the condenser. If necessary, clean the condenser using a vacuum. We suggest a vacuum be used to prevent any damage to the condenser coil. Most Ordered Parts', 4),
    ('644404eb-435e-557b-9b33-899da64292eb'::uuid, 'Pitco Soup Rethermalizer', 'CHECK UNIT FOR MISSING/WORN PARTS', 'Look for anything that seems broken or worn. Pay special attention to the supply hose because this is known to go bad. It is best to replace parts when they still have a little life left in them. Potentially Needed Parts', 1),
    ('2e425c3c-2233-5503-b2d7-46373253ecff'::uuid, 'Taylor Ice Cream Machine', 'INSPECT TUNE-UP KIT PARTS FOR CRACKS AND DAMAGE (REPLACE IF PRESENT)', 'These are the o-rings and seals that are sold in a kit. These items do not really affect the machines performance but more of it''s cleanliness. Cracked and damaged o-rings will cause the machine to leak ice cream base. Even if they seem in good shape, go ahead and change them if its been more than 3 months since you last did so.', 1),
    ('435642b5-207e-5a99-9346-994b0ae8c485'::uuid, 'Taylor Ice Cream Machine', 'INSPECT SCRAPPER BLADES FOR CRACKS AND DAMAGE (REPLACE IF PRESENT)', 'Scraper blades are the white plastic blades that attach to the beaters. If these are cracked nicked or damaged they will affect the performance of the machine. Even if they seem in good shape, go ahead and change them if its been more than 3 months since you last did so.', 2),
    ('a44d9c06-7e23-5d8e-abf6-ffeb957fa3e8'::uuid, 'Taylor Ice Cream Machine', 'CLEAN CONDENSERS OF DIRT/ DEBRIS', 'Remove the sides of the machine and clean off the condensers. At the very least the outside vent openings should be cleaned.', 3),
    ('5ecbb642-733e-5d47-ba43-5b1a5d09d975'::uuid, 'Taylor Ice Cream Machine', 'INSPECT/ REPLACE BOOTS ON MIXERS(SPINNERS)', 'The mixer/spinner switch should be covered by a plastic boot. This boot helps to protect the mixer/spinner from being damaged by excess shake base or ice cream.', 4),
    ('c1a6ddc8-1f2d-5ea3-9b43-47cfa6af1b74'::uuid, 'Taylor Ice Cream Machine', 'INSPECT REAR SHELL BEARING FOR SIGNS OF WEAR/ CLEANLINESS', 'The shell bearing is the part of the machine that the drive shaft is inserted into, on the inside of the mixing chamber (see below). Using a flash light inspect inside the mixing chamber for any signs or wear or dirt to the shell bearing. You can cover a screwdriver with a cloth to help clean the back of the mixing chamber.', 5),
    ('53169b98-9d91-5ebf-83f4-99136109f5a0'::uuid, 'Taylor Ice Cream Machine', 'INSPECT BELT FOR WEAR', 'With the machine off, remove the back cover and inspect the belts for signs or wear or dry rotting. Replacing these belts at the first sign wear will avoid unnecessary down time.', 6),
    ('6bbcc5bd-fee9-52e6-830a-b25150571d11'::uuid, 'Taylor Ice Cream Machine', 'INSPECT UNIT ACCORDING TO TAYLOR GUIDELINES', 'This inspection should be done by a Taylor certified tech. We recommend that it is done yearly as a tune up to ensure the machine is running as efficiently as possible. At the very least have they Taylor tech run through this checklist anytime they are out for a service call. Smallwares', 7)
), equipment_match as (
  select distinct on (lower(name)) lower(name) as name_key, id
  from public.equipment
  order by lower(name), id
), matched as (
  select seed_rows.id, equipment_match.id as equipment_id, seed_rows.title, seed_rows.details, seed_rows.sort_order
  from seed_rows
  join equipment_match on equipment_match.name_key = lower(seed_rows.equipment_name)
)
insert into public.equipment_pm_tasks (id, equipment_id, title, details, sort_order)
select id, equipment_id, title, details, sort_order from matched
where not exists (
  select 1 from public.equipment_pm_tasks existing where existing.id = matched.id
);

-- Seed equipment_reference_sections.
with seed_rows(id, equipment_name, section_type, title, body, source_page, sort_order) as (
  values
    ('4c20c5b7-7729-5353-a691-9537b33235a0'::uuid, 'AJ Antunes Breakfast Toaster', 'reference', 'Overview & tips', E'AJ Atunes has a 24/7 support line available at the number above.\nNovice Skill Level\nCurtain Assembly\nFeet\nDeep Clean\nModerate Skill Level\nFans\nConveyor Belt\nCord\nCall a Pro\nHeating Element\nMelted Wires\nFaulty Control Board\nThe breakfast toaster comes equipped with two curtains (One in the front and one in the back) that help keep the heat\ninside the machine.\nIf you have not preformed routine maintenance on this machine in a while then, you may not see any of the curtain left.\nTo replace: When the machine is cool, take a flat head screw driver and pry off old curtains to remove. Place one side\nof new curtain on the mounting peg and bend to place the other side on opposite peg.\nFront and Back Curtain Location (Pictures by AJ Atunes)\nIt is important to clean the top and bottom fans once a quarter to keep the machine running efficiently. Over time\ngrease and dust collects on the fan blades and can keep the fan from spinning. If the fans stop working then the\nmachine will overheat and shut down.\nTo clean the fans: Remove the three screws (See image below) to access the inside of fan and clean the blades with a\nsoft brush (I USE THESE) or wet towel with a mild degreaser. Then reattach the screws and wipe down the outside.\nMake sure the fan blades are clear of debris.\nLook at page 10 of the USER MANUAL for more details about cleaning\nTop and Bottom Fan Screw Locations (Pictures by AJ Atunes)', 4, 1),
    ('41c2a2a6-7d74-52c3-a1b9-ffd532b92da8'::uuid, 'AJ Antunes Bun Toaster', 'reference', 'Overview & tips', E'AJ Antunes has a 24/7 support line available at the number above.\nNovice Skill Level\nConveyor belts\nFeet\nTop Insert Teflon\nDeep Clean\nModerate Skill Level\nFan\nThermostat\nTensioner\nChains\nPower Cord\nCall a Pro\nContactor\nMelted wires\nHaving a well maintained conveyor belt wrap and chain will affect the quality of your toasted buns. It is important to\nclean these once a month for stores doing more than 7 million a year, or at least once a quarter.\nTo clean, remove the belt wrap from the chain. If you have a zipper on your belt wrap, save yourself time and cut it off\nand order a new style that is much easier to remove and clean (CLICK HERE TO ORDER). If the wrap is melted or\nhas significant build up, it is better to replace it and focus on cleaning the wrap more often moving forward.\nIf the wrap has minor build up, use a scrub pad and degreaser to get the wrap clean. Then use a brush tool to clean\nbetween the conveyor chain (I USE THIS BRUSH). You can also carefully spray degreaser on this chain making sure\nto sanitize all parts following the cleaning and let dry.\nLook at page 11 and 14 of the USER MANUAL for more details about cleaning.\nIf you have never cleaned your belt wraps or chain, then odds are there is significant oil and grease build up on them.\nYou can spend a lot of time trying to clean them, but it maybe cheaper and a better use of your time to just replace\nthem. The replacement of theses parts are is easy and quick.\nIf you have to replace your chains (CLICK HERE TO ORDER) and belts (CLICK HERE TO ORDER), start to clean the\nbelt wrap and chains on a monthly basis. This will help you from having to replace them again because of build up.\nIf you are a higher volume store and you only have one toaster, you can ask your facilities rep for an additional toaster.\nThis will allow you to rotate your toasters each month and have a backup in case one breaks.\nWhen you received your toaster, it came with an item that looks like a long metal spatula (CLICK HERE TO ORDER).\nWhile this can be used to get stuck buns out, it is intended to be used to clean the platen (the part in the middle that\nheats the teflon). If there is buildup of carbon on the heat plate it can cause toast quality issues. Place a blue scrubby\nbetween the two-saw tooth (not on the side with the teeth) openings and scrub the platen\nThere are also new spatulas due to the blue scrubby not staying in place. (CLICK HERE TO ORDER). You will also\nhave to buy the new scrub pads (CLICK HERE TO ORDER).\nSee page 10 of USER MANUAL for more detailed instructions.', 9, 1),
    ('06696414-3b95-582a-9dbc-ca7d9cdedfd2'::uuid, 'AJ Antunes Egg Cooking Station', 'reference', 'Overview & tips', E'AJ Atunes has a 24/7 support line available at the number above.\nThe front of the egg cooker works kind of like a phone screen. If water or oil gets anywhere on the front, it can keep\nbuttons from functioning properly. If you are having trouble wipe the front blue control decal with hot soapy water, dry,\nwipe with a sanitizer wipe and dry again. If the issue persists the control board may need replaced. This should restore\nthe screen''s functionality.\nleaning the front display is a common repair for many other issues as well so it''s a great starting point when making\nrepairs to the griddle.\nIssues related to this repair:\nUnit does not turn on\nUnit turns on then turns off\nTimer is not responsive\nTimer ends early\nUnit is not responsive\nIf you are experiencing eggs running to one side or the other, you can level the machine. Each of the four legs/feet are\nadjustable. Turn the leg counter clockwise to shorten and clockwise to lengthen.\nEnsure proper cleaning procedures are being followed when cleaning the griddle\nVerify wires in the plug are tight and there is no debris/ water present in the plug.\nMake sure there are no signs of burned wires are scorch marks\nIf the above issues are good, then remove the bottom of the griddle and inspect the insulation around the heating\nelement connections. Any oil present around this area can cause the breakers to trip. Cut away the insulation around\nthe heating element connections. Remove the connections to the heating elements and clean each piece of hardware\nwith a sanitizer wipe and allow to dry. Put the unit back together and test. If issue persists have an electrician check\nthe outlet and breaker. Other issues may persist in the unit as well that will require a certified service tech.\nE009 High control board temperature\nEnsure the vents and the fan on the underside are free from debris. If they are dirty clean with a lightly damp cloth and\ndegreaser. If the fan is not operating while the unit is on it may be faulty and need replaced.\nE101 Hi-limit\nAllow the unit to cool for 20 minutes. Remove the hi- limit cap at the rear of the unit and press the green reset button. If\nissue persists the hi-limit or solid-state relay could be faulty.', 15, 1),
    ('f936a100-532a-5c62-89e7-cbd74ade7e88'::uuid, 'AJ Antunes Soup Warmer', 'reference', 'Overview & tips', E'AJ Antunes has a 24/7 support line available at the number above.\nNovice Skill Level\nReplace Feet\nReplace Drain Assembly\nReplace Thermostat Knob\nModerate Skill Level\nReplace Thermostat\nReplace Cord\nReplace Heating Element\nCall a Pro\nMelted wires\nTRYING TO KEEP SOUP HOT?\nWhen using the CW-100 soup warmer, be sure to use or cover all of the top opening. This will maximize the amount of\nheat that the warmer is able to transfer to the soup.\nLOOKING FOR PARTS?\nAlthough parts manuals are difficult to find, you can find the few parts that need to be replaced on Parts Town.\nMost of these parts can be replaced with a screw driver and wrench, and require minimal technical skills.\nNEED TO DESCALE?\nTo remove scale: Mix 1 tsp. white vinegar to 1 cup of water, let stand, rinse, repeat if necessary. We recommended\nyou descale once a quarter or more often if buildup is severe.', 17, 1),
    ('82038c3c-5f8c-5bb1-ad12-3055e004b555'::uuid, 'Alto-Shaam Vector Oven', 'reference', 'Overview & tips', E'Novice Skill Level\nHandle\nFilter\nModerate Skill Level\nMotor\nBlower\nPower Switch\nSpeaker\nCall a Pro\nControl Board\nTouch Screen\nIf your screen is frozen or won''t turn on/off then you need to reset the oven. Turn off the oven using the big switch on\nthe back. Wait 30 seconds and then turn it back on. That should reset it.\nThe handle on the vector oven is really easy to replace. All you need is a philips head screwdriver and 3 screws. Don''t\npay anyone to make this repair. Click the following links for parts: Handle, Screw ( M5 x 0.8 x 35mm, Pan, Phillips) x3,\nWasher ( M5, Split Lock, DIN #127B) x 3.\n(The OEM screws and split washers are expensive at over $3 each, you could save some money finding similar parts\ncheaper, but you always run the risk that they won''t work as well.)\nThese machine run pretty well without much maintenance. One task that needs to be done on a monthly basis is to\nclean or replace the filters on the back and inside of the oven. When the oven is off and cooled, remove the filters. You\ncan clean them by spraying them out with a hose, or running them through the dishwasher. Shake out excess water,\nlet them dry and reinstall.\nIf you need to get into the advanced setting the factory password is 1946. The manual says 12345 but it has been\nreprogramed by corporate.', 19, 1),
    ('b65c3fe9-d039-5360-8cd5-0e051b79fb60'::uuid, 'BKI Fry Warmer', 'reference', 'Overview & tips', E'Option 4\nNovice Skill Level\nLight Bulb\nModerate Skill Level\nPlug\nCord\nBlower & Heater Assembly\nBulb Holder\nCeramic Top Heaters\nRocker Switch\nCall a Pro\nMelted wires\nThe bulbs in the passthru are designed to run in high heat environments. To help extend the life of your bulb, do not\ntouch it with your bare hands when you are installing it. The oils on your hands can be transferred to the bulbs,\ncreating hot spots that lower the life of the bulb. In order to prevent this, wear gloves when touching and installing the\nbulb.\nIf the pass thru part of the fry warmer is hot, but the air coming out of the perforated pan is warm, than you most likely\nneed to replace your blower and heater assembly (CLICK HERE TO ORDER).', 21, 1),
    ('b23b1a92-ca4d-566b-a69f-f6f540775f7b'::uuid, 'BKI Pass Thru Chute', 'reference', 'Overview & tips', E'Option 4\nNovice Skill Level\nLight Bulb\nModerate Skill Level\nPlug\nCord\nBulb Holder\nCeramic Top Heaters\nRocker Switch\nCall a Pro\nMelted wires\nThe bulbs in the passthru are designed to run in high heat environments. To help extend the life of your bulb, do not\ntouch it with your bare hands when you are installing it. The oils on your hands can be transferred to the bulbs,\ncreating hot spots that lower the life of the bulb. In order to prevent this, wear gloves when touching and installing the\nbulb.', 23, 1),
    ('dd0b6d4a-ca11-5806-bfc5-7e71a0173301'::uuid, 'Blodgett Oven', 'reference', 'Overview & tips', E'Support Operating Hours:\nMonday - Friday\n8:00 am - 5:00 pm (EST)\nNovice Skill Level\nKnob\nBulb\nModerate Skill Level\nMode Selector\nRocker Switch\nFuse\nCall a Pro\nContactor\nMelted wires\nThe Blodgett oven is an extremely reliable oven that does not require much work. In our 12 years of combined\nexperience we have needed to preform minimal work on this machine.\nOne of the biggest factors in keeping this machine running is preforming regular cleaning of the oven.', 25, 1),
    ('cd6fd70a-4f30-58ec-a55e-b2036ed3e475'::uuid, 'Centerline (Hobart) Dishwasher', 'reference', 'Overview & tips', E'Franke:\nAll Other Companies:\nNovice Skill Level\nSide Skirts\nOil Bin\nModerate Skill Level\nLid Gap Adjustment\nCasters\nButton\nRocker Switch\nPlug\nCall a Pro\nActuator\nControl Screen\nHeater\nMelted Wires\nGarland grills are fairly complex machines and a lot is at risk when they are not working correctly. Because of this,\nmost repairs should be done through a certified repair service.\nMake sure smooth side of chicken is facing down to create the best grill marks.\nPoint tips towards outside of grill, the fat ends should be towards the center of the grill.\nMake sure nuggets are at least .5 inch away from the sides as these are cooler areas on the grills.\nMake sure no product is touching other product.\nOnly 10 sausages max on the cook surface .\nIf these don''t fix the issue your grill surfaces may be warped, damaged, or the gap calibration may be off.\nThere are many reasons as to why the Garland Grill is not cooking chicken evenly/fully. One cause can be if the side\nskirts are not properly installed or broken. The side skirts help to maintain heat in the grill and cook the chicken evenly\nand fully.\nTo clean the tops of the grills, close the top platen by pressing the green button then shutting the unit off using the\npower switch. While the unit is hot,use sizzle and a green scrub pad. Make sure to wear heat resistant gloves.\nThere are sensors on the top of the grill that must not be scraped or have any chemicals used on them. If you are not\ncareful with cleaning you could cause an error code on the grill. Clean using the damp towel, feed the towel onto the\ntop part of the sensor then "floss" the towel back and forth applying pressure in the downwards motion.\nIf the sensors are dirty and you are getting an error code the first step is to clean these sensors until they are free of\nbuildup ( back to a silver color). If the sensors are damaged they can be a costly repair due to having to open up the\ntop portion of the grill to get to the parts.\nThere are life expectancies on many components of the grill! To avoid breakdowns its recommended a service tech is\ncalled to replace parts when life expectancy is low.\nTo check life component tracking go into "diagnostics" scroll down to "advanced" press start "component life tracking"\npress start. This brings you to the screen where you can see how much life is left on components of the grill. Call a\nservice tech if any component is in the red (Less than 20%)', 27, 1),
    ('f99b3895-1fd7-5cf3-ae92-6485f9734077'::uuid, 'Champion Dishwasher', 'reference', 'Overview & tips', E'Support is available\n8:00am-5:00pm\nMonday - Friday\nNovice Skill Level\nWash Arm\nFilter Screen\nTrack/Rail\nDeep Clean\nRinse Arm\nModerate Skill Level\nUpper Fan\nHoses\nDoor Spring\nBreaker\nHeater Flange\nScreen\nCall a Pro\nMotors\nValves\nElectrical\nMelted wires\nMost stores have experienced difficulties with these machines, but the positive aspect is that they have excellent\ntechnical support. It is advisable to contact Champion before requesting a technician as they can guide you through\ntroubleshooting procedures and advise whether the repairs can be carried out on-site or if a technician needs to be\ncalled.\nThe factory default password is "7777".\nThis is helpful for adjusting\ncycle times\nconcentration\nrinse-aid\nThe factory default maintenance screen password id "9999"\nIf your machine is acting up you can reset the machine.\nSelect the tool icon, then enter the code 9999 and select Service Reset.\nThis is a great thing to try before calling out a tech, if the machine is acting up.\nWhen it comes to purchasing parts, it is generally recommended to opt for OEM (original equipment manufacturer)\nproducts. However, this does not apply to dish racks used in dishwashers. OEM racks can cost over $150, while other\nbrands with equivalent quality can be purchased for less than $30. We recommend the dish rack below, which we\nhave used ourselves and found to be durable.\nIf you need a new screen call champion for that part. They will need to send out a screen that is programed for your\nbrand. They will also send out instructions on how to do the install.', 29, 1),
    ('0c6eaef2-53b2-5df0-bd51-aae0d4c06702'::uuid, 'Compartment Sink (T&S)', 'troubleshooting', 'Troubleshooting', E'T&S Sink Drain Parts\nT&S Sink Drain Installation\nNovice Skill Level\nDelime\nModerate Skill Level\nGasket\nO-Ring\nHandle\nPlunger\nStop Leak\nPVC Drain Repair\nComplete Drain\nCall a Pro\nFloor Drains\nComplete PVC Replacement\nT & S drains are designed to be able to lock a strainer into place to keep losing the strainer to a minimum. CLICK\nHERE to order the strainer with the lock. And CLICK HERE to view a video on how to install.\nThere are also other options for strainer locks that are one piece. CLICK HERE to view Drain Armor Strainer. I have\nbeen using this brand in my store for almost 2 years with no problem.\nStandard Compartment sinks have a 3.5" drain size but be sure to confirm your size before purchasing.\nIf you have a sink that slowly leaks water then you likely need to replace the o-ring on the plunger. Simply remove the\nstrainer and with the drain in the open position, use pliers/screw driver to remove the old o-ring. Install the new o-ring\nand check for a good seal.\nIf the leak still continues it could be the other o-rings in the handle or the gasket between the drain and the sink. View\nthe parts manual for the location of these o-rings.\nCLICK HERE to order a replacement plunger o-ring.\nCLICK HERE to order replacement o-rings for the whole drain.\nIf you have to replace the whole drain, go ahead and order the drain installation tool. This inexpensive tool will save\nyou time and frustration on the removal of your old flange and installing your new drain.\nCLICK HERE to order the installation tool.', 31, 1),
    ('97a75852-5c70-545c-bb8d-a419c910284a'::uuid, 'Compartment Sink (T&S)', 'troubleshooting', 'Troubleshooting', E'T&S Sink Sprayer Parts\nT&S Sink Sprayer w/ Hose Parts\nNovice Skill Level\nDelime\nModerate Skill Level\nBumper\nHandle\nFace\nHose\nBonnet\nFull Replacement\nIf your sprayer is not working correctly, you can replace parts over replacing the while unit. The most common items\nthat need to be replaced are the spray valve face and the spray valve bonnet.\nIf you do by a new one, this replacement does not change out the handle as this is part of the hose assembly\nIf your sprayer seems to have low water pressure check the spray valve face and see if the holes are blocked with\nhard water build up. If they are, unscrew the face from the sprayer and use the needle part of your name tag to clean\nthem out. You can also replace the face for less than $5. We recommend replace the face plate once a year.\nThey sell the hose attachment for the sprayer in various sizes. You can get a hose with a handle that is 12" all the way\nup to 96" and everywhere in between. The standard sizes are 36" or 44". CLICK HERE TO SEE A LIST OF HOSE\nSIZES (Make sure you select one with the handle).', 32, 2),
    ('2d149ea4-e289-5f47-8824-e45f6bbb42c8'::uuid, 'Crathco Lemonade Dispenser', 'troubleshooting', 'Troubleshooting', E'gmcw.com\nThe service desk is open from 8:00 am to 4:30 pm CST.\nNovice Skill Level\nGasket\nImpeller\nPush Handle\nFilter\nModerate Skill Level\nMotor\nPlug\nCord\nRocker Switch\nFan Motor\nCall a Pro\nCompressor\nCondenser\nMelted wires\nTo maximize the life and efficiency of these machines it is important to make sure they are getting proper airflow.\nMaximizing airflow can be done in two important ways:\n1) Make sure there is at least 2 inches of space on each side of the machine and 3 inches of space in the rear.\n2) Clean the filters under the machine each week to provide maximum airflow. These filters can easily become\nclogged by spilled drinks. The filters should be replaced every 6 months as part of preventive maintenance\nThere are two areas that this sound can come from. One being the fan motor inside the unit. This is a simple repair by\nunplugging the unit and removing the front panel to remove the motor. The other area this sound can come from is\nfrom a failed compressor which is around $1,000 repair. Have a certified service tech verify if this is the case and if so\nreach out to your field consultant on how they would like to handle the repair if this is the case. A dirty condenser coil\nis most often the cause of a failed compressor. Keeping up with the cleaning of the coils will be the best way to\nprolong the life of the compressor\nSwap the black impeller with another one from the unit. If the issue is resolved, then the black impeller needs replaced\nas they do wear overtime. This is part of a PM kit located under the expanded parts list\nIf the issue is not fixed by the impeller being replaced, then we could have a faulty impeller motor or the magnet above\nthe motor has slipped down and needs to be moved back up. Unplug the unit and remove the rear panel to inspect.\nThe common cause of this is from the dispensing valve being bent. This part can either be straightened out or\nreplaced to correct the issue. To reduce risk of this happening next time, it is recommended to have team members\ndisassemble the unit, promptly clean the parts, and bring them back upfront to airdry. This minimizes the risk of parts\nfalling off the tables in the back at night.\nThe parts that create the seal to the bowl assembly are small and easy to lose. Keep an extra of each on hand for the\ntimes when you lose one. This way you don''t have to run a lunch rush down a machine. CLICK HERE TO SEE\nPARTS', 34, 1),
    ('776df66a-bcdc-5807-ae2b-92d135ab291a'::uuid, 'Crathco Lemonade Dispenser', 'troubleshooting', 'Troubleshooting', E'gmcw.com\nThe service desk is open from 8:00 am to 4:30 pm CST.\nBowl Assembly\nMotors\nMisc.\nkeep red button items on hand\nMiscellaneous Parts', 35, 2),
    ('67fb19fc-d945-5d51-86f0-dc7778393d16'::uuid, 'Curtis Coffee Brewer', 'reference', 'Overview & tips', E'The Techinal Service line is available\nM-F 5:30A - 4:00P PST\nS&D does all the servicing of tea and coffee brewers for Chick-fil-a\nNovice Skill Level\nSprayhead\nFuse\nModerate Skill Level\nControl Board\nWater Inlet Valve\nFaucet Handle\nWater Level Probe\nCall a Pro\nHeating Element\nMelted wires\nIf you have a problem with your coffee and tea brewer call S&D Coffee and Tea before you attempt any repairs\nyourself. S&D will typically handle all parts ordering and repairs. They also provide yearly equipment checks and\ncalibration at no cost to the store.\nAn S&D Manager will visit each Chick-fil-A Restaurant once a year to perform the following tasks:\nCalibrate the coffee brewer\nVerify the coffee brewer is cleaned\nVerify the coffee brewer is functioning as designed\nS&D Customer Service will notify the Restaurant of the maintenance visit, 24- 48 hours in advance.\nThe S&D Manager will avoid the Restaurant between the hours of 11:00 am and 1:00 pm when possible.\nThe coffee maintenance program covers all coffee brewer and parts\nThe coffee maintenance program does not cover the Fresh Track Coffee Server\nS&D Customer Service will provide Chick-fil-A, Inc. a monthly service report of all service issues\nOver time it is common for leaks to form on internal components. This is especially true if your store has hard water. If\nyou noticed water leaking from the inside, immediately unplug the machine and call out a tech. Failing to do so could\ncause serious injury to your team.\nTake apart the spray heads at least once a month to clean out any hardwater and debris that may be affecting the\nwater output. The tabs do break easily so it is a good idea to have some on hand. The coffee brewers use the amber\nspray heads.', 37, 1),
    ('f1e2ee8f-f0a3-5389-8eb9-3c2833872512'::uuid, 'Curtis Tea Brewer', 'troubleshooting', 'Troubleshooting', E'S&D does all the servicing of tea and coffee brewers for Chick-fil-a\nCalibration Guide 5 Gallon\n3 Gallon\nNovice Skill Level\nSprayhead\nFuse\nModerate Skill Level\nControl Board\nWater Inlet Valve\nWater Level Probe\nCall a Pro\nHeating Element\nMelted wires\nIf you have a problem with your coffee and tea brewer, call S&D Coffee and Tea before you attempt any repairs\nyourself. S&D will typically handle all parts ordering and repairs. They also provide yearly equipment checks and\ncalibration at no cost to the store.\nIf your tea brewer is not brewing the correct amount, and your tea is stronger or weaker than it should be, you can\nrecalibrate it using the recalibration guide.\nYou can also contact S&D Coffee and ask them when you are due for your yearly calibration. Sometimes they will\ncome early if you are close to the date of your yearly visit.\nRed spray heads MUST be in place when performing the calibration to have accurate readings.\nThere is a gasket on the inside located between the spout and your tea urn body. Remove the nozzle and then take an\n11/16 allen wrench and stick it in to the nozzle hole from the outside. Turn to tighten. The threading is backwards so\nIt''s lefty tighty, righty loosey on this one. Go left and it''s going to tighten it up.\nAn S&D Manager will visit each Chick-fil-A Restaurant once a year to perform the following tasks:\nCalibrate the coffee brewer\nVerify the coffee brewer is cleaned\nVerify the coffee brewer is functioning as designed\nS&D Customer Service will notify the Restaurant of the maintenance visit, 24- 48 hours in advance.\nThe S&D Manager will avoid the Restaurant between the hours of 11:00 am and 1:00 pm when possible.\nThe coffee maintenance program covers all coffee brewer and parts\nThe coffee maintenance program does not cover the Fresh Track Coffee Server\nS&D Customer Service will provide Chick-fil-A, Inc. a monthly service report of all service issues\nOver time it is common for leaks to form within internal components. This is especially true if your store has hard\nwater. If you noticed water leaking from the inside, immediately unplug the machine and call out a tech. Failing to do\nso could cause serious injury to your team.\nTake apart the spray heads at least once a month to clean out any hardwater and debris that may be affecting the\nwater output. The tabs do break easily so it is a good idea to have some on hand. The coffee brewers use the amber\nspray heads.', 39, 1),
    ('c1775cf0-e0fa-5a0f-9259-e934a92de1db'::uuid, 'Duke Breading Table', 'troubleshooting', 'Troubleshooting', E'To minimize the risk of the ice bath breading table getting caught up in the pegs of the shelving system and causing\nthousands of dollars in damage to the table, install a barrier or a bar between the ice bath breading table and the\nshelving. This can be done by reaching out to your field consultant to have the work performed.', 41, 1),
    ('ac785e46-3456-57af-8e1a-cdcd6902d69e'::uuid, 'Follett Ice Maker', 'troubleshooting', 'Troubleshooting', E'Normal Hours\nMonday - Friday\n8:00 a.m. to 5:00 p.m. EST\nEmergency After-Hours\n5:00 pm to 8:00 pm EST\nSaturday, Sunday\n8:00 am to 8:00 pm EST\n1410 User Manual\n1410 Parts Manual\n1650 User Manual\n1650 Parts Manual\n1810 User Manual\n1810 Parts Manual\nNovice Skill Level\nGasket\nModerate Skill Level\nDeep Clean\nDeclog Drain\nWater Sensor\nInlet Valve\nMotor\nAuger\nPower Cord\nCall a Pro\nCompressor\nMelted wires\nBecause the water draining from the bottom of your ice bin is just above freezing it can easily clog your drain line\nunder the machine. If you have another floor drain nearby that is under a sink try to push most of the ice to that drain.\nThe warm water from the sink will help keep grease from solidifying as easily.\nThe required quarterly cleaning is not impossible to do, but it is fairly involved. We recommend paying a company to\ndo it or receiving training to do it properly. With the risk of bacteria growing in the supply lines, it is best to leave it to a\nprofessional.\nIf you have water pooling in the bottom of the ice bin then your bin drain is clogged. Be careful cleaning it during the\nday because build up from the line can go back into the bin and contaminate all of your ice.\nIf possible, wait until close and empty out your bin. Then using a shop vac suction out the line from the bottom drain.\nThis should allow your bin to drain freely. The best way to prevent this from happening is emptying and cleaning your\nice bin monthly. When performing this cleaning, be sure to clean out the bin drain.\nEach Follett Ice Maker has two components to it. There is the part on top of the ice bin that makes the ice and then\nthere is a condenser unit on the roof. These different parts are typically on separate breakers. If the condensing unit is\noff, it may not show on the control panel light panel.\nIf you can hear parts running on the section on top of the ice bin but it does not seem cold check your condenser unit\nand make sure it is working properly.', 42, 1),
    ('83370304-e724-534d-892b-b2a752df2348'::uuid, 'Franke Chicken Warming Station', 'reference', 'Overview & tips', E'Option 2\nModerate Skill Level\nCord\nHeating Element\nRocker Switch\nToggle Switch\nCall a Pro\nMelted wires\n1.Provide contact with the customer:\n- Within 30 minutes of request for service during normal business hours\n- Within 90 minutes after normal business hours (including weekends)\n2. Perform service visit:\n- The same day for emergency service*\n- Within 24 hours for standard service\n3. Target a 90% "first call" fix rate\n4. Provide 90-day warranty on the service performed\n*An "emergency" is defined as an equipment operating condition that poses an immediate risk to the safety of\nrestaurant workers or customers.\nStagger the turn on of both levels till you need them. Many store only use one level during breakfast, if this is the case\nthen don''t turn on the second level till you need it. This will help save electricity in powering the machine, extend the\nlife of the machine and keep unneeded heat out of the kitchen\nThere are a few things to look at when the unit is not heating\nIs the unit plugged in?\nIs the outlet or breaker tripped?\nFaulty power switch\nFaulty heating element\nFaulty wiring', 44, 1),
    ('d0f721ab-92ed-567c-9234-4fec3f1fe2ca'::uuid, 'Garland Grill', 'reference', 'Overview & tips', E'Novice Skill Level\nSide Skirts\nOil Bin\nModerate Skill Level\nLid Gap Adjustment\nCasters\nButton\nRocker Switch\nPlug\nCall a Pro\nActuator\nControl Screen\nHeater\nMelted Wires\nGarland grills are fairly complex machines and a lot is at risk when they are not working correctly. Because of this,\nmost repairs should be done through a certified repair service.\nTo clean the tops of the grills, close the top platen by pressing the green button then shutting the unit off using the\npower switch. While the unit is hot,use sizzle and a green scrub pad. Make sure to wear heat resistant gloves.\nThere are sensors on the top of the grill that must not be scraped or have any chemicals used on them. If you are not\ncareful with cleaning you could cause an error code on the grill. Clean using the damp towel, feed the towel onto the\ntop part of the sensor then "floss" the towel back and forth applying pressure in the downwards motion.\nIf the sensors are dirty and you are getting an error code the first step is to clean these sensors until they are free of\nbuildup ( back to a silver color). If the sensors are damaged they can be a costly repair due to having to open up the\ntop portion of the grill to get to the parts.', 46, 1),
    ('a4989d6d-6a7d-5277-9d4b-267318cc1666'::uuid, 'Henny Penny CFE 410 / 420', 'reference', 'Overview & tips', E'Henny Penny has an excellent 24/7 support line available at the number above.\nCFE 410/420 Technical Manual\nCFE 410/420 Buttons and Programing\nCFE 410/420 Parts Manual\nOFE 321 Manual\nOFE 321 Parts Manual\nNovice Skill Level\nHose Nipple\nLatch on pan lid (410/420)\nDeep Clean\nTighten Element Spreaders\nModerate Skill Level\nMicro Switch\nHigh Limit\nControl Board\nPlug\nCord\nHeating Element\nSolenoid Valve\nPump/Motor\nJib Pump (410/420)\nCall a Pro\nContactor\nMelted wires\nOn the back wall of each Henny Penny vat there are two lines. It is easy to think these are minimum and maximum\nlines, but that is not the case. These are actually lines that tell you how much oil you need for a fill up based on\nwhether the machine is hot or cold. If you are turning your machine on for the day your oil should reach the bottom\nline. If your machine is hot and you are only topping off the oil it should go to the top line.\nWhy? Oil expands when it heats up, this means if you fill up a cold machine to the top line, then it will be overfull once\nit warms up.\nHenny Penny has phenomenal technical support. When in doubt give them a call and they can talk you through any\nissues that could be fixed without needing a tech to come out. This could save you $150-400 depending on the fees of\nyour service provider.\n410/420 Fry fryers manufactured prior to December 2020 have a different high limit probe and module compared to fry\nfryers manufactured after December 2020.\nWhen there is a E-10 high limit error on the fry fryer and the rocker reset switch has been pushed then there error\ncould be the probe, module, or control board. Make sure you are ordering the module and probe if you are not sure.\nWhen doing boil outs, it''s important to remove your reserve tank and empty it of oil. Then spray the inside of the box\nand let air dry. Small crumbs can get into the reserve box causing the jib pump to get clogged up. This could cause\nyou to need to replace the whole jib motor itself.\nIf you are using a CFE 410/420 and you get a change pad error, it is likely that your micro switch at the bottom, back of\nthe machine is dirty. Try cleaning it with a mild degreaser and a rag. If this doesn''t fix your issue, then you will need to\nreplace the micro switch (CLICK HERE TO ORDER PART).\nThe replacement of this part is a pretty easy fix. Using a phillips screw driver and and adjustable wrench take off the\nback cover and the old switch. Unplug one wire at a time from the old switch and plug it into the same spot on the new\nswitch. Then repeat with the other wire. Reinstall the new switch and back cover.\nUnexplained Oil on the Ground with the CFE 410 Fryer\nIf you have a newer CFE 410/420 and experience an unexplained puddle of oil coming from underneath the machine,\nthen it could be a bad hose connected to the pump. There was a manufacturing period when faulty hoses were being\nused in new CFE 410-420''s causing them to leak oil. We had it happen to both our new machines that were installed\nin Spring of 2021.\nIf this puddle happens several days in a row, this is likely the problem.\nRemove the flex line and measure has there are different lengths throughout the pump system.\nWhen a new piece of Henny Penny equipment comes with a warranty, it does not cover a service call for an issue that\nwas caused by lack of cleanliness (like a nugget or crumb stuck in a filter line or oil in places it should not be) or\ndamage from mistreatment (closing lids/doors to hard or dropping or running something into the equipment).\nSo, before you call out a tech, turn off the machine and clean it really well. Check to see if the problem can be fixed by\ncleaning out the affected area. If the tech fixes the problem and it is a cleanliness or damage issue, you will be\nresponsible for paying the bill. If the issue is caused by a manufacturer defect, the service call will be covered under\nwarranty.\nTechs have a lot of discretion on who to charge, you or the warranty company. This is where treating a tech well can\nplay in your favor. If a good relationship exists, they maybe more likely to bill the warranty on an issue that could go\neither way.\nMost Ordered CFE 410/420 Parts\nKeep red button items on hand.', 50, 1),
    ('dabc92e9-548b-5142-9006-0a7e4f45d0ee'::uuid, 'Henny Penny CFE 415', 'reference', 'Overview & tips', E'Henny Penny has an excellent 24/7 support line available at the number listed above.\nNovice Skill Level\nHose Nipple\nLatch on Pan Lid\nModerate Skill Level\nMicro Switch\nHigh Limit\nReplace a Board\nPlug\nCord\nHeating Element\nPump/Motor\nJib pump\nCall a Pro\nContactor\nMelted wires\nOn the back wall of each Henny Penny vat are two lines. It is easy to think these are Minimum and Maximum lines but\nthat is not the case. These are actually lines for cold machine filling or hot machine filling. If you are turning your\nmachine on for the day your oil should reach the bottom line. If your machine is hot and you are only topping off oil it\nshould go to the top line.\nWhy? Oil expands when it warms up, this means if you fill up a cold machine to the top line, then it will be overfull once\nit warms up. This is especially important with pressure fryers. Overfilling a machine will force oil to overflow into your\nsteam(solenoid) valve on the top right side and will cause your exhaust stack to spit out grease and water.\nHenny Penny has a phenomenal technical support. When in doubt give them a call and they can talk you through any\nissues that could be fixed without needing a tech to come out. This could save you $150-400 depending on the fees of\nyour service provider.\nIf you are using a CFE 415 and you get a change pad error, it is likely that your micro switch at the bottom, back of the\nmachine is dirty. Try cleaning it with a mild degreaser and a rag. If this doesn''t fix your issue, then you will need to\nreplace the micro switch (CLICK HERE TO ORDER PART).\nThe replacement of this part is a pretty easy fix. Using a phillips screw driver and and adjustable wrench take off the\nback cover and the old switch. Unplug one wire at a time from the old switch and plug it into the same spot on the new\nswitch. Then repeat with the other wire. Reinstall the new switch and back cover.\nWhen doing boil outs, it''s important to remove your reserve tank and empty it of oil. Then spray the inside of the box\nand let air dry. Small crumbs can get into the reserve box causing the jib pump to get clogged up. This could cause\nyou to need to replace the whole jib motor itself.\nWith as much use as equipment gets, it is important to get issues fixed quickly. One of the best ways to know if\nsomething is broken is to inspect the equipment frequently. We recommend a detailed inspection for each narrow fryer\nat least once a month. These inspections can be as quick as 15 minutes if no issues arise. We also recommend\ncleaning and lubricating the machine during this inspection.\nOn the fryers you are looking for:\nLeaks in any of the pipes\nO-Rings on filter pan\nHigh Limited and thermometer cleanliness\nCorrectly installed element spreaders (no missing screws)\nBecause of the narrowness of the CFE 415, it must be attached to a pressure fryer in the back. The right side of the\nnarrow fryer is attached to the the left side of the pressure fryer. The fryer has to be attached because there is risk of\nthe fryer tipping over causing a major safety risk. There is no fourth caster leg insert made for this fryer\nWhen looking at the machines from behind, It is typically attached using 2 hinge brackets. These brackets hinge which\nallow for access and removal of the side panel of both machines. This is very important when making repairs on the\nbottom half of the Henny Pennys.\nThe down fall of these machines being attached is when you have to have one machine moved to the back to be\nserviced, both machines must be unplugged and moved.\nIf you the front of the control board to your Henny Penny 415 is cracked or peeling you can replace it without replacing\nthe whole control panel. Order a new control board decal (CLICK HERE TO ORDER PART).\nWith the machine unplugged remove the old screen and clean off residue. The new decal comes with a 3m strip type\nglue on the back. You just need to remove backing from new decal and carefully line up and place it on the machine.\nWhen your machine stops pumping oil, and the pump isn''t making any noise, there are several things you can try. One\nof them is to try the red reset button on the side of the motor. Sometimes pressing this button will allow the pump to\nwork again. The reserve pan will have to be removed on this unit in order to access the red reset button on the motor.\nYou have to use a screw driver to press this button until it clicks. The button can not be pressed hard enough by hand.\nIf it does not click the motor or stops working shortly after, it will likely need to be replaced.', 57, 1),
    ('5a1e31f9-81d6-5fb7-a3b8-7e674f642860'::uuid, 'Henny Penny PFE 500', 'reference', 'Overview & tips', E'Henny Penny has an excellent 24/7 support line available at the number listed above.\nNovice Skill Level\nLid Gasket\nHose Nipple\nModerate Skill Level\nMicro Switch\nReplace a Board\nPressure Gauge\nPressure Release Valve\nHigh Limit\nPlug\nSolenoid Valve\nCord\nHeating Element\nPump/Motor\nCall a Pro\nSpindle/Cross Arm/ Lid\n(see tips and tricks section)\nContactor\nMelted wires\nOn the back wall of each Henny Penny vat there are two lines. It is easy to think these are minimum and maximum\nlines, but that is not the case. These are actually lines that tell you how much oil you need for a fill up based on\nwhether the machine is hot or cold. If you are turning your machine on for the day your oil should reach the bottom\nline. If your machine is hot and you are only topping off the oil it should go to the top line.\nWhy? Oil expands when it warms up and when it''s under pressure, this means if you fill up a cold machine to the top\nline, then it will be overfull once it warms up and builds pressure. This is especially important with pressure fryers.\nOverfilling a machine will force oil to overflow into your steam (solenoid) valve on the top right side and will cause your\nexhaust stack to spit out grease and water.\nHenny Penny has phenomenal technical support. When in doubt give them a call and they can talk you through any\nissues that could be fixed without needing a tech to come out. This could save you $150-400 depending on the fees of\nyour service provider.\nIssues with the lid of the pressure fryer are fairly common. In the past they were a pretty easy fix (usually a $5 Idle or\nAcme nut pin). Recently, however, Henny Penny changed their lid assembly. They no longer sell individual parts but\nyou have to replace the whole thing. It went from a potential $5-20 fix to a $1,200-1,600 fix.\nThe good news is that these repairs are often covered by corporate as a TBR. If you are having an issue with your lid\nreach out to your Facilities Rep and let them about the issue. If the solution is to replace the lid, then it should be\ncovered by corporate. This is where building a good relationship with your facilities rep comes in (CLICK HERE for\nmore on that)\nThis one is simple, but worth noting. With as much use as your equipment gets, it is important to get it fixed quickly.\nOne of the best ways to know if something is broken is to inspect the equipment frequently. We recommended a\ndetailed inspection for each pressure fryer at least once a month. These inspections can be as quick as 15 minutes if\nno issues arise. We also recommend cleaning and lubricating the machine during this inspection\nOn the pressure fryers be sure to look for:\nCracks in the cross arm\nLeaks in any of the pipes\nCleanliness and Lubrication of all lid assembly pieces\nA correct limit stop adjustment\nCleanliness of the pressure relief valve\nClogs in the exhaust stack and drain tube\nMissing screws on the element spreader\nWhen a new piece of equipment comes with a warranty, it does not typically cover a service call for an issue that was\ncaused by lack of cleanliness (a nugget or crumb stuck in a filter line or oil in places it should not be) or damage from\nmistreatment(closing lids/doors too hard or dropping or running something into the equipment).\nBefore you call out a tech, turn off the machine and clean it really well. Check to see if the problem can be fixed by\ncleaning out the affected area. If the tech fixes the problem and it is a cleanliness or damage issue, you will be\nresponsible for paying the bill. If the issue is caused by a manufacturer defect, the service call will be covered under\nwarranty.\nTechs have a lot of discretion on who to charge, you or the warranty company. This is where treating a tech well can\nplay in your favor. If a good relationship exists, they maybe more likely to bill the warranty on an issue that could go\neither way.', 61, 1),
    ('4be9ead1-7e92-5976-bb4a-c19d6e3230f4'::uuid, 'Hobart Mixer', 'troubleshooting', 'Troubleshooting', E'1-888-4HOBART\nwww.hobartservice.com\nNovice Skill Level\nCup Drip and Flange\nSlicer Shelf Magnet\nThumb Screw\nModerate Skill Level\nBowl Lift Handle\nPlug\nCord\nFeet Pads\nCall a Pro\nMotor\nTransmission\nMelted wires\nPay attention to the cup, drip and flange (the part that holds the wire bowl guard in place). This piece is know to crack\nand break off right into the mixing bowl. This is a major food safety hazard and should be addressed immediately if\ncracks or chips are noticed.\nTo replace, remove the bowl guard and remove the three screw on the cup, drip and flange. Press down on this piece\n(you may need to use a rubber mallet). Install new piece and line up screw holes. Reinstall the screws to secure the\ncup, drip and flange to the Hobart.', 77, 1),
    ('3bb6a635-64ad-5ab4-b06d-2d3f4dd8bc49'::uuid, 'Hobart Mixer', 'troubleshooting', 'Troubleshooting', E'1-888-4HOBART\nwww.hobartservice.com\nMixer Parts\nAttachment Parts', 78, 2),
    ('d3d9c652-fa24-5ce6-9e98-957bc6d09a9b'::uuid, 'KanPak Milkshake Base Dispenser', 'reference', 'Overview & tips', E'We recommend call KanPak with any issues. There is a partnership that covers all parts or a replacement of the\nmachine.\nTo help minimize the growth of bacteria and smells it is important to clean the dispenser daily. Stores should clean the\ninterior, dispensing valves, dispensing valve area and drip tray on a daily basis. See the PM Schedule for more\ndetailed cleaning.', 80, 1),
    ('2568f98e-3843-557a-971e-0cc139c6afb3'::uuid, 'Lang Oven / Griddle / Hotplate', 'reference', 'Overview & tips', E'www.langworld.com\nPress option 2 during normal business hours Monday to Friday 7:00am to 8:00pm CST.\nIf after hours call 800-264-7827\nThere are no good service manuals for the SCR30 Combo. If you search by the machine name on Parts Town, you\nhave a good shot of finding the parts you need that are not listed below. CLICK HERE.\nNovice Skill Level\nFilter\nModerate Skill Level\nMotor\nBlower\nPower Switch\nBuzzer\nFrench Plates\nRotary Knob\nGriddle Heating Element\nKnobs\nCord\nCall a Pro\nMelted Wires (very common)\nOven Heating Element\nIf you are getting power to your lang, but not every part is working (Hot Plates, Griddle, or Oven), then you may have a\ntripped internal breaker.\nAfter unplugging the machine, or turning off at the main breaker, locate the panel attached by screws on the right side.\nRemove these screws and locate the internal breakers (typically lower right). See if any of these are tripped, causing\nonly part of the machine not to work. If none of these are tripped and you still are only getting partial power then you\nhave a more complicated issue.\nIt is very common for wires to melt on this machine. I have had to replace 3 switches and all the wiring over the course\nof 6 months. If you find melted wires, it is best to pay a pro to come in and make sure everything is running correctly\nand that there isn''t a short somewhere.', 82, 1),
    ('ab5689a5-5d02-5a04-a694-e956fc664229'::uuid, 'Merco Hot Holding Cabinet', 'reference', 'Overview & tips', E'MHC52SNT1T, Merco Service Desk, Documents, The title of each item on the screen tells you how to set it up., photo by merco (page\n3-4), In-House Repair Recommendations\nwww.mercoproducts.com/Service\nThe type of product you are storing in your merco will determine the type of lid you use (or don''t) and what type of\nfalse bottom you use (or don''t). You can tell what each product needs or doesn''t need by looking at it''s title on the\nscreen. It is important to follow these instructions as it can impact the machine ability to hold your food at the correct\ntemperature and quality.\nNovice Skill Level\nDeep Clean\nModerate Skill Level\nPower Cord\nPower Relay\nSpeaker\nPower Switch\nCall a Pro\nHeating Element\nContactor\nMelted wires', 84, 1),
    ('b35a65ec-e316-537d-814c-0ba056f4e77c'::uuid, 'Nugget Chopper', 'reference', 'Overview & tips', E'AJ Atunes boasts a 24/7 support line available at the number above.\nNemco Support is available weekdays 8:00 A.M. to 5:00 P.M. Eastern time.\nIf your pusher plate is bend and causing damage to your blade you can adjust the push plate using a screw driver and\npliers. Test the adjustment by attempting to close the handle and seeing if it makes contact with the blade.\nIf you want to help keep the countertop clean you can order a slide out for your chopper even if you don''t have a\ncenterline.\nTo order fill out a help ticket and they will connect you with your Trimark Rep.\nKeep red button items on hand.', 86, 1),
    ('cf3c54e2-de1d-5a30-9b55-72b9bf8fafbc'::uuid, 'Pitco Soup Rethermalizer', 'reference', 'Overview & tips', E'Phone: +1 (603) 225-6684\nOption 2\nE-mail: service@pitco.com\nWeb: www.pitco.com\nThe service desk is open 24/7\nThe OEM (original equipment manufacturer) hose is very expensive at over $800. Do not use a gas line hose or\nwasher machine hose as they are not food safe and pose a greater risk to flooding overtime. There is a cheaper\nsolution while maintaining the OEM specs (ORDER HERE). This is a great option for only $278, a $500 dollar savings.\nReuse the same connections and thread sealant when making the swap.\nIf you are getting the code HEAT FAILURE on your rethermalizer, then it is likely your hi limit has been tripped. Wait a\nfew minutes and press the reset button. If this doesn''t work, you may need to replace the hi limit.\nThere are two water level probes on the front left-hand side of the unit. If these have any buildup of hardwater, debris,\nor are wet then the unit thinks the water level is good and starts heating which then sends the unit into heat failure.\nUse a poker brush at the end of the night to keep these sensors clean. Dry the sensors off in the morning to get the\nunit to fill. If the unit still does not fill, then there are some areas to look into\nReplace the water level probes\nVerify water is on\nVerify the hose connections at the wall and the unit are secure (May need to shut the water off to release some\npressure to connect them together)\nWater solenoid is faulty, and needs replaced.\nIt is very important to maintain the cleanliness of the unit. This includes making sure there is no debris from busted\nbags at the bottom of the unit and proper deliming procedures. To delime the unit, heat the unit up when not in use\nand put in two delimer tablets into the tank. Let these soak for at least an hour, drain, then use a sanitizer towel to\nwipe everything clean. Hard water deposits can build up and causes issues with draining.\nNovice Skill Level\nDeep Clean\nDeliming\nModerate Skill Level\nHigh Limit\nPlug\nCord\nHeating Element\nDrain Valve\nHose\nCall a Pro\nMelted wires', 88, 1),
    ('29848d12-1c2a-5723-9132-9c44aed2161d'::uuid, 'Pitco Soup Rethermalizer', 'troubleshooting', 'Troubleshooting', E'Phone: +1 (603) 225-6684\nOption 2\nE-mail: service@pitco.com\nWeb: www.pitco.com\nThe service desk is open 24/7\nDescale Unit\nAny cleaning agent used must be safe for use with food contact surfaces and safe for stainless steel.\nFollowing the manufacturer''s instructions of the deliming product you are using, remove deposits from the tank''s\ninterior.\nWhen cleaning is complete, rinse the inside of the tank and its components thoroughly with cool, potable water.\nContinue to rinse at least twice, or until all of the deliming product has been completely and thoroughly rinsedfrom the\ntank.\nUsing a clean, dry cloth, wipe out all of the water from the tank.\nCHECK UNIT FOR MISSING/WORN PARTS\nLook for anything that seems broken or worn. Pay special attention to the supply hose because this is known to go\nbad. It is best to replace parts when they still have a little life left in them.\nPotentially Needed Parts', 89, 2),
    ('5b4702ea-fa9a-5756-8b52-67bf89e65b9e'::uuid, 'Randell Cold Holding Cabinet', 'reference', 'Overview & tips', E'Novice Skill Level\nFilter\nLid\nModerate Skill Level\nPower Cord\nPlug\nCondenser Fan\nCondenser Motor\nPower Switch\nCall a Pro\nCompressor\nCondensor\nExpansion Valve\nControl\nProbe', 91, 1),
    ('849a91b0-87e9-54db-adf6-3d714f365aa2'::uuid, 'Star Hot Plate', 'reference', 'Overview & tips', E'www.star-mfg.com\nThe service desk is open 8:00 am to 4:30 p.m. Central Standard Time\nAfter a long day in the kitchen, it is easy to overlook cleaning the soup pot when shutting down for the night. Continual\nneglect, however, can lead to the equipment failing. This is especially true if your store has hard water, because the\nbuild up caused by the water can eat away at important components.\nIt is very important to not overfill the pots with water. When the soup thaws it will sink down further into the pot\ndisplacing water and causing it to overflow over the sides. This overflow can get into the internal components and\ncause damage.\nThere is a parts manual available on this page, but you can also find the few parts that need to be replaced on Parts\nTown. CLICK HERE TO VIEW PARTS or view most common parts below.\nMost of these parts can be replaced with a screw driver and wrench and require minimal technical skills.\nNovice Skill Level\nDeep Clean\nReplace Legs\nModerate Skill Level\nController\nPlug\nCord\nElement/French Plate\nIndicator light\nCall a Pro\nMelted wires', 93, 1),
    ('a2dbfa22-9742-55ea-bc94-1f4a962a6783'::uuid, 'Taylor Ice Cream Machine', 'reference', 'Overview & tips', E'Taylor Support\nTaylor does not offer robust over the phone support. Their solution is often to have a tech come out instead of helping\nyou resolve remotely.\nNovice Skill Level\nChange out Scrapers\nChange out O-Rings\nModerate Skill Level\nReplace Spinners\nReplace Spinner Motor\nSwitch\nCall a Pro\n95% of Taylor Repairs. It is a very complicated machine and tech support is not very helpful. It is not fun to pay the\nprice, but mostly likely you will have to at some point, so better to take care of it sooner than later.\nWhen your milkshake spinner stops working well or even working at all, it is usually one of two things: the switch or the\nspinner motor. The switch costs around $30 and the motor costs between $175-300 (see below for why there is a\nrange). Always start with the cheaper option, a new switch, and if your problem is still around, then replace the motor.\n[Always remember to unplug the machine if you are doing this repair yourself. It is one of the few repairs that we\nrecommend a mechanically minded team member doing in-house on the Taylor Machines.]\nWhen replacing the switch doesn''t fix your broken spinner, the next thing you should try is to replace the spinner motor\nitself.\nThere are two ways to make this repair. One is cheaper ($150-$175) and fairly easy, but this repair can be a bit finicky.\nThe other way is super easy, with less room for error, but more expensive ($230-$260). So, the cheaper option is to\nreplace the motor inside of the housing (CLICK HERE) . The easier option is to change the whole set (CLICK HERE).\nTo change out the motor you must remove the spinner by loosening the 4 bolts on its face and removing the plastic\nquick disconnect. Then you must open up the top of the spinner remove the old motor and replace with the new. It is\npretty straight forward, but it is a tight fit and you have to get it just right. Once the new motor is in place, then\nreconnect the spinner disconnect and reattach it to the machine.\nThe easier but more expensive option is replacing the whole assembly. Remove the spinner from the machine by\nloosening the 4 bolts on its face and removing the plastic quick disconnect. Then connect the new assembly to the\ndisconnect and attach with the 4 screws. That is it!\nINSTRUCTIONS FOR CHANGING THE WHOLE SPINNER (CLICK HERE)\nINSTRUCTIONS FOR CHANGING THE MOTOR (CLICK HERE)\nThere are two main "parts" that need to be routinely replaced on the ice cream machine, the o-ring tune up kit and the\nscraper blades. According to a Talyor Tech, the blades are more important to change consistently than the o-rings.\nScraper blades should be changed every 2 weeks to every month depending on sale volume. Replacing the blades\nhelps the machine to work more efficiently and can help in regard to efficient freeze time. O-Rings should be changed\nevery month as part of the tune-up kit, or whenever you notice that product is leaking when not in use. The o-rings\nhave minimal effect of the efficiency of the machine but are more about cleanliness and ease.\nTaylor Machines are very complicated machines and there is not a lot of information out there on how to fix them.\nTaylor is very adamant that they are the only ones that should service these machine and they provide little to no help\nover tech support.\nBecause of this, it is usually better to only use Taylor to service these machines and do very few repairs in house.\nEven though it is not fun paying their steeper price, it will save you time and money in the long run by calling them right\naway.\nAs mentioned above, Taylor Machines are complex and can have further issues if not handled correctly. Sometimes\nthe issues that you are experiencing are caused from doing one of the set up steps incorrectly at open.\nFor issues that you are unsure of the cause, break the machine down and put it back together carefully before you call\na tech. The last thing you can try, is replacing the scraper blades. This will cost you less than $20 and could save you\nhundreds on an unnecessary service call.\nThe ice cream machine is one of the messiest pieces of equipment in the store. It is not uncommon for ice cream and\nshake base to get everywhere, including running down the side of the machine and covering the condenser coils.\nWhen this happens it can cause a wide range of problems. Visit the Preventative Maintenance page for the Taylor to\nfind out more about cleaning the coils (CLICK HERE TO VIEW PM PAGE).\nParts town sells the Taylor lubricant in a case of 36. While this does save money in the long run, it will take some time\nto go through the lubricant to which storage can be hard to come by. When buying Taylor lubricant make sure you are\ngetting the one with the blue label as this is the one meant for the Taylor freezer models.', 95, 1),
    ('7109bd29-9fe6-54a5-bade-c1252a4f6c83'::uuid, 'Toastmaster Warming Drawer', 'reference', 'Overview & tips', E'www.star-mfg.com\nStar also owns toastmaster. The service desk is open 8:00 am to 4:30 p.m. Central Standard Time.\nSingle Drawer Parts\n2, 3, or 4 Drawer Parts\nThe rails need to be lubricated periodically. It is best to grease them as soon as it starts to become difficult to open\nand close the drawer, to avoid damaging the rails. Remove the rails them by pushing back as far as possible, grasping\nthe rail and tilting it inward from the top.\nAfter removing the rails, grease the ball bearings with a high temperature, food grade grease gun (CLICK HERE TO\nSEE EXAMPLE OF GREASE).\nImage by Toastmaster\nNovice Skill Level\nDrawer\nDrawer Rails (3rd channel)\nKnob\nModerate Skill Level\nThermostat\nIndication Light\nLatch\nHandle\nHeating Element\nCall a Pro\nFull Replacement\nCaught on Fire', 99, 1),
    ('c97ae814-5ed3-53e7-a283-07c1d59290ea'::uuid, 'Traulsen Low Boy', 'troubleshooting', 'Troubleshooting', E'Phone: +(800) 825-8220\nWeb: www.traulsen.com\nThe service desk is open Monday thru Friday 7:30 am - 4:30 pm CST.\nNovice Skill Level\nAdjusting Temperature\nChange Gasket\nReplace Wheels\nDeep Clean\nReverse Door Swing\nModerate Skill Level\nEmpty Drain/Condensation Pan\nReplace Motor\nReplace Drain Line\nReplace Power Cord\nHinge Replacement\nCall a Pro\nCompressor\nLow on Charge\nMelted wire\nIf there is water inside the table, then there is likely a clogged condenser drain line. Remove the back panel where the\ncompressor is. In the middle, there is an opaque line that feeds into a tray at the bottom. Attach a shop vac to the line\nand clear the clog. If you were able to get water out through the line then this should resolve your issue of internal\nwater.\nAlternatively, there could be a hole in your condensation drip tray that is inside your fridge, where the top of the drain\nhose attaches.\nThe side the doors on the Traulsen Undercounter Refrigerators open from are designed to be easily reversed. This\ncan help save your team from having to step out of the way every time they need access to a fridge.\nTo reverse the door: Support the end of the door furthest from the hinges so that the door does not fall when you\nremove the screws. Remove lower hinge from the fridge and then top hinge. The lower hinge is under tension so be\ncareful when removing this part from the fridge.\nRemove both doors and then reverse their positions on the fridge. Make sure that the lower hinge is under tension\nagain by extending it before you install it. This job is easiest with a second pair of hands.\nIf you are replacing the gaskets on the doors yourself, sometimes they can be difficult to install or do not create a good\nseal around the door. We recommend that you place them in the dishwasher for less than 2 minutes or use a heat gun\nto make it easier to put them in place and create a better seal.\nIf your door is not closing properly, try heating the gasket up using a hair dryer or heat gun on the low setting and run it\nover the gasket a few times. Then close the door and hold it there for a minute. This will reset your door gasket\ncreating a better seal. If the door still doesn''t close right then the spring hinge may need to be replaced.\nThere are no good parts manuals for Traulsen lowboy fridges. Click the button for the model number that you have to\nsearch by the machine name on Parts Town. This will bring up many of the parts you may need. You can also call\nTraulsen at the number above for help with parts numbers and where to buy them.', 101, 1),
    ('71923d5c-6ade-5a1a-90f4-715466bbf6bc'::uuid, 'Traulsen Prep Table', 'reference', 'Overview & tips', E'Traulsen Prep Table\nPhone: +(800) 825-8220\nWeb: www.traulsen.com\nThe service desk is open Monday thru Friday\n7:30 am - 4:30 pm CST\nLimited Parts Catalog\nNovice Skill Level\nDoor Gasket\nChange Wheels\nChange Filter\nModerate Skill Level\nPlug\nCord\nDeclog Evaporator Drain\nDoors\nHinges\nCall a Pro\nCompressor\nEvaporator\nMelted wires\nIf there is water inside the table then there is likely a clogged condenser drain line. Remove the outside panel where\nthe compressor is. Towards the bottom there is an opaque line that feeds into a tray. Attach a shop vac to the line and\nclear the clog. If you were able to get water out through the line then this should resolve your issue of internal water.\nIf the pins for the lid assemblies break it is best to replace the whole lid. There are no rebuild kits for this part. We have\ntried several different things to avoid buying a new lid but in the end they didn''t work.\nIf you are replacing the gaskets on the doors yourself, sometimes they can be difficult to install or do not create a good\nseal around the door. We recommend that you place them in the dishwasher for less than 2 minutes or use a heat gun\nto make it easier to put them in place and create a better seal.\nIf your door is not closing properly, try heating the gasket up using a hair dryer or heat gun on the low setting and run it\nover the gasket a few times. Then close the door and hold it there for a minute. This will reset your door gasket\ncreating a better seal. If the door still doesn''t close right then the spring hinge may need to be replaced.\nThere are no good parts manuals for Traulsen Products. Click the button for the model number that you have to\nsearch by the machine name on Parts Town, this will bring up many of the parts you may need.\nYou can also call Traulsen''s service desk for help with parts numbers and where to buy parts.\nLid Assemblies', 103, 1),
    ('7cc95c4d-9726-558d-aacb-78d953e64d07'::uuid, 'Traulsen Thaw Cabinet', 'reference', 'Overview & tips', E'Traulsen Thaw Cabinet\nPhone: +(800) 825-8220\nWeb: www.traulsen.com\nThe service desk is open Monday thru Friday\n7:30 am - 4:30 pm CST\nNovice Skill Level\nDoor Gasket\nChange Wheels\nChange Filter\nModerate Skill Level\nPlug\nCord\nDeclog Evaporator Drain\nDoors\nHinges\nBlower/Motor\nCall a Pro\nCompressor\nEvaporator\nMelted wires\nIf you are replacing the gaskets on the doors yourself, sometimes they can be difficult to install or do not create a good\nseal around the door. It is recommended to use a heat gun to make it easier to put them in place and create a better\nseal.\nIf your door is not closing properly, try heating the gasket up using a hair dryer or heat gun on the low setting and run it\nover the gasket a few times t 6-8 inches away from the gasket. Then close the door and hold it there for a minute. This\nwill reset your door gasket creating a better seal. If the door still doesn''t close right, then the hinges may need\nadjusted. Remove the hinge covers and on the door side of the hinge there are three screws. Loosen or remove the\nscrews and just behind the screws is a grooved plate. Slide that plate to the left or right to adjust the door then\nreassemble. If the issue persists the hinges may need replaced.\nMake sure the door seal is good and the doors stay closed. The product inside the unit may need readjusted to make\nsure the door is staying closed.\nClean the prefilters and the condenser coils located on top of the unit. Dirty coils are the number one cause of\ncompressor failures.\nDo not buy hinges. Instead call the manufacture as they are lifetime warranty\nIf the door is not making a good seal or is left open for an extended period of time, then the compressor runs longer to\nmake up for the temperature inside the unit. This causes excessive water and overfills the evaporator pan on top of\nthe unit and overflows. If the door is closed and the seal is good, then we could have some faulty components, and an\nauthorized service agent will need to look further into the issue.\nIf there is excess water inside the cabinet then there is likely a clogged condenser drain line. Pull out the unit and\nplace a ladder behind the unit. Under the perforated covering you will see a long tray with a tube leading into it.\nRemove the outside perforated panel where the compressor is. Attach a shop vac to the line and clear the clog. If you\nwere able to get water out through the line then this should resolve your issue of internal water.\nThere are no good parts manuals for Traulsen thaw cabinets. Click the button for the model number that you have to\nsearch by the machine name on Parts Town, this will bring up many of the parts you may need. You can also call\nTraulsen at the number above for help with parts numbers and where to buy them.', 105, 1)
), equipment_match as (
  select distinct on (lower(name)) lower(name) as name_key, id
  from public.equipment
  order by lower(name), id
), matched as (
  select seed_rows.id, equipment_match.id as equipment_id, seed_rows.section_type, seed_rows.title, seed_rows.body, seed_rows.source_page, seed_rows.sort_order
  from seed_rows
  join equipment_match on equipment_match.name_key = lower(seed_rows.equipment_name)
)
insert into public.equipment_reference_sections (id, equipment_id, section_type, title, body, source_page, sort_order)
select id, equipment_id, section_type, title, body, source_page, sort_order from matched
where not exists (
  select 1 from public.equipment_reference_sections existing where existing.id = matched.id
);
